public class StringComparisonDemo {
    public static void main(String[] args) {
        // Literals are interned - same object in memory
        String s1 = "Java";
        String s2 = "Java";
        System.out.println(s1 == s2);        // true (same reference)
        System.out.println(s1.equals(s2));   // true (same content)

        // Runtime construction creates new object
        String s3 = new String("Java");
        System.out.println(s1 == s3);        // false (different reference)
        System.out.println(s1.equals(s3));   // true (same content)

        // User input simulation
        String userInput = "Ja" + "va";      // concatenation creates new object
        System.out.println(s1 == userInput);        // false (different reference)
        System.out.println(s1.equals(userInput));   // true (same content)
    }
}

import java.util.*;

public class CompareToDemo {
    public static void main(String[] args) {
        // Basic compareTo examples
        System.out.println("apple".compareTo("banana"));  // negative (apple < banana)
        System.out.println("zebra".compareTo("apple"));   // positive (zebra > apple)
        System.out.println("test".compareTo("test"));     // 0 (equal)

        // Sorting with TreeSet - uses compareTo automatically
        var names = new TreeSet<String>();
        names.addAll(List.of("Charlie", "Alice", "Bob"));
        System.out.println(names);  // [Alice, Bob, Charlie] - sorted

        // Manual sorting decision
        String user1 = "Smith";
        String user2 = "Johnson";
        if (user1.compareTo(user2) < 0) {
            System.out.println(user1 + " comes first");
        }
    }
}

public class StringSearchDemo {
    public static void main(String[] args) {
        String email = "user@company.com";
        String filename = "report.pdf";
        String logEntry = "ERROR: Database connection failed at 14:23";

        // contains() - simple presence check
        if (email.contains("@")) {
            System.out.println("Valid email format");  // true
        }

        // startsWith() and endsWith() - boundary checks
        if (filename.endsWith(".pdf")) {
            System.out.println("PDF file detected");  // true
        }
        if (logEntry.startsWith("ERROR")) {
            System.out.println("Error log entry");    // true
        }

        // indexOf() - find position for parsing
        int atPosition = email.indexOf("@");
        if (atPosition != -1) {  // check if found
            String username = email.substring(0, atPosition);  // "user"
            System.out.println("Username: " + username);
        }
    }
}

import java.util.Locale;

public class CaseInsensitiveDemo {
    public static void main(String[] args) {
        String userInput = "Admin";
        String expected = "admin";

        // Correct way - equalsIgnoreCase
        if (userInput.equalsIgnoreCase(expected)) {
            System.out.println("Access granted");  // true
        }

        // Sorting case-insensitively
        String name1 = "smith";
        String name2 = "JONES";
        if (name1.compareToIgnoreCase(name2) > 0) {
            System.out.println(name1 + " comes after " + name2);  // true
        }

        // Dangerous approach - locale-sensitive
        Locale.setDefault(new Locale("tr", "TR"));  // Turkish locale
        String turkish = "I";
        System.out.println(turkish.toLowerCase().equals("i"));  // false - breaks!
        System.out.println(turkish.equalsIgnoreCase("i"));     // true - correct
    }
}

import java.util.Objects;

public class NullSafeComparisonDemo {
    public static void main(String[] args) {
        String userInput = null;  // simulating missing input
        String expected = "admin";

        // UNSAFE - throws NullPointerException
        // if (userInput.equals(expected)) { ... }  // CRASH!

        // SAFE - Objects.equals() handles nulls
        if (Objects.equals(userInput, expected)) {
            System.out.println("Match");  // false, no crash
        }

        // SAFE - literal-first pattern
        if ("admin".equals(userInput)) {
            System.out.println("Authorized");  // false, no crash
        }

        // Objects.equals() null behavior
        System.out.println(Objects.equals(null, null));     // true
        System.out.println(Objects.equals(null, "test"));   // false
        System.out.println(Objects.equals("test", null));   // false
    }
}
